package br.com.swconsultoria.nfe.util;

import br.com.swconsultoria.nfe.dom.ConfiguracoesNfe;
import br.com.swconsultoria.nfe.dom.Evento;
import br.com.swconsultoria.nfe.dom.enuns.AmbienteEnum;
import br.com.swconsultoria.nfe.dom.enuns.EstadosEnum;
import br.com.swconsultoria.nfe.exception.NfeException;
import br.com.swconsultoria.nfe.schema.envEventoCancNFe.TEnvEvento;
import br.com.swconsultoria.nfe.schema.envEventoCancNFe.TEvento;
import org.junit.Before;
import org.junit.Test;

import java.time.ZoneId;
import java.util.ArrayList;
import java.util.List;

import static org.junit.Assert.*;

public class MontaCancelamentoTests {

    private ConfiguracoesNfe configuracao;
    private List<Evento> listaEventos;

    @Before
    public void setUp() {
        configuracao = new ConfiguracoesNfe();
        configuracao.setAmbiente(AmbienteEnum.HOMOLOGACAO);
        configuracao.setEstado(EstadosEnum.SP);
        configuracao.setZoneId(ZoneId.of("America/Sao_Paulo"));

        listaEventos = new ArrayList<>();
        Evento evento = new Evento();
        evento.setChave("12345678901234567890123456789012345678901234");
        evento.setCnpj("12345678000195");
        evento.setCpf(null);
        evento.setDataEvento("2023-01-01T10:00:00");
        evento.setProtocolo("123456789012345");
        evento.setMotivo("Cancelamento por erro de digitação");
        listaEventos.add(evento);
    }

    @Test
    public void testMontaCancelamentoSuccess() throws NfeException {
        TEnvEvento result = CancelamentoUtil.montaCancelamento(listaEventos, configuracao);

        assertNotNull(result);
        assertEquals("1", result.getIdLote());
        assertEquals(1, result.getEvento().size());

        TEvento tEvento = result.getEvento().get(0);
        assertNotNull(tEvento);
        assertEquals("12345678901234567890123456789012345678901234", tEvento.getInfEvento().getChNFe());
        assertEquals("1", tEvento.getInfEvento().getCOrgao());
        assertEquals("2", tEvento.getInfEvento().getTpAmb());
        assertEquals("12345678000195", tEvento.getInfEvento().getCNPJ());
        assertNull(tEvento.getInfEvento().getCPF());
        assertEquals("123456789012345", tEvento.getInfEvento().getDetEvento().getNProt());
        assertEquals("Cancelamento", tEvento.getInfEvento().getDetEvento().getDescEvento());
        assertEquals("Cancelamento por erro de digitação", tEvento.getInfEvento().getDetEvento().getXJust());
    }

    @Test(expected = NfeException.class)
    public void testMontaCancelamentoThrowsExceptionWhenMoreThan20Events() throws NfeException {
        List<Evento> eventos = new ArrayList<>();
        for (int i = 0; i < 21; i++) {
            eventos.add(new Evento());
        }
        CancelamentoUtil.montaCancelamento(eventos, configuracao);
    }

    @Test
    public void testMontaCancelamentoWithCPFInsteadOfCNPJ() throws NfeException {
        Evento evento = listaEventos.get(0);
        evento.setCnpj(null);
        evento.setCpf("12345678901");

        TEnvEvento result = CancelamentoUtil.montaCancelamento(listaEventos, configuracao);

        TEvento tEvento = result.getEvento().get(0);
        assertNull(tEvento.getInfEvento().getCNPJ());
        assertEquals("12345678901", tEvento.getInfEvento().getCPF());
    }

    @Test
    public void testMontaCancelamentoMultipleEvents() throws NfeException {
        Evento evento2 = new Evento();
        evento2.setChave("98765432109876543210987654321098765432109876");
        evento2.setCnpj("98765432000198");
        evento2.setDataEvento("2023-01-02T11:00:00");
        evento2.setProtocolo("987654321098765");
        evento2.setMotivo("Cancelamento por duplicidade");
        listaEventos.add(evento2);

        TEnvEvento result = CancelamentoUtil.montaCancelamento(listaEventos, configuracao);

        assertEquals(2, result.getEvento().size());

        TEvento firstEvent = result.getEvento().get(0);
        assertEquals("12345678901234567890123456789012345678901234", firstEvent.getInfEvento().getChNFe());

        TEvento secondEvent = result.getEvento().get(1);
        assertEquals("98765432109876543210987654321098765432109876", secondEvent.getInfEvento().getChNFe());
    }

    @Test
    public void testMontaCancelamentoWithProductionEnvironment() throws NfeException {
        configuracao.setAmbiente(AmbienteEnum.PRODUCAO);

        TEnvEvento result = CancelamentoUtil.montaCancelamento(listaEventos, configuracao);

        TEvento tEvento = result.getEvento().get(0);
        assertEquals("1", tEvento.getInfEvento().getTpAmb());
    }
}

