                sb.append("Array detectado com ").append(arraySize).append(" elemento(s)\n");
                sb.append("Validacao realizada no primeiro elemento\n\n");
            }

            if (extraFields.isEmpty() && missingFields.isEmpty() && typeErrors.isEmpty()) {
